import express from "express";
import authMiddleware from "../middlewares/authMiddleware.js";
import {
  getPostController,
  getNewPostController,
  getPostSearchController,
  createPostController,
  getPostByIdController,
  getPostSuggestController,
  getPostByUserIdController,
  hiddenPostController,
  getPostFollowController,
  incrementPostViewController,
  monthlyPostCountController,
  topViewPostController,
  getRecentPostController,
  adminHiddenPostController,
  postCategoryCountController,
} from "../controllers/postController";
import { adminMiddleware } from "../middlewares/adminMiddleware.js";

const router = express.Router();

router.get(
  "/statitic/monthly-posts",
  authMiddleware,
  adminMiddleware,
  monthlyPostCountController
);
router.get("/statitic/top-view", authMiddleware, adminMiddleware, topViewPostController);
router.post(
  "/admin/hidden/:postId",
  authMiddleware,
  adminMiddleware,
  adminHiddenPostController
);
router.get(
  "/statitic/post-category",
  authMiddleware,
  adminMiddleware,
  postCategoryCountController
);
router.get("/recent", authMiddleware, getRecentPostController);
router.get("/get-all", getPostController);
router.get("/get-new", getNewPostController);
router.get("/get-follow", authMiddleware, getPostFollowController);
router.get("/get-suggest", getPostSuggestController);
router.get("/:userId", getPostByUserIdController);
router.get("/search/:keyword", getPostSearchController);
router.get("/:id/detail", getPostByIdController);

router.post("/create", authMiddleware, createPostController);
router.post("/hidden/:postId", authMiddleware, hiddenPostController);
router.post(
  "/increment-view/:postId",
  authMiddleware,
  incrementPostViewController
);

export default router;

